// Source-to-shard guard for the non-Ubuntu TestWriterReplay shards. The
// manifests in testdata/writer-shards are generated by gen/gen-writer-shards.mjs
// from the template and golden files alone; these tests recompute the
// assignment from loadWriterTemplates and require every caseID exactly once.

const (
	writerShardCount = 4
	writerRecorderID = "recorder-fake-docker"
)

// writerShardForCase is SHA256(UTF-8(id))[0] mod 4 (spec 3.1); the generator
// duplicates the rule independently.
func writerShardForCase(id string) int {
	sum := sha256.Sum256([]byte(id))
	return int(sum[0]) % writerShardCount
}

type writerShardManifest struct {
	Shard           int      `json:"shard"`
	Ordinary        []string `json:"ordinary"`
	Posix           []string `json:"posix"`
	Golden          int      `json:"golden"`
	WindowsPass     int      `json:"windowsPass"`
	WindowsSkip     int      `json:"windowsSkip"`
	WindowsCompared int      `json:"windowsCompared"`
}

func loadWriterShardManifest(t testing.TB, repo string, shard int) writerShardManifest {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(repo, "difftest", "testdata", "writer-shards", fmt.Sprintf("shard-%d.json", shard)))
	if err != nil {
		t.Fatal(err)
	}
	return parseWriterShardManifest(t, raw)
}

func parseWriterShardManifest(t testing.TB, raw []byte) writerShardManifest {
	t.Helper()
	var m writerShardManifest
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&m); err != nil {
		t.Fatalf("malformed writer shard manifest: %v", err)
	}
	if dec.More() {
		t.Fatal("malformed writer shard manifest: trailing data")
	}
	return m
}

// quoteAlt is an anchored, quoted alternation of ids.
func quoteAlt(ids []string) string {
	q := make([]string, len(ids))
	for i, id := range ids {
		q[i] = regexp.QuoteMeta(id)
	}
	return "^(?:" + strings.Join(q, "|") + ")$"
}

// writerShardFilterFor builds the -run pattern for a manifest. Go splits -run
// on '/' per subtest level, so the ordinary ids and the literal level "posix"
// share level two and the posix ids are level three, under "posix/".
func writerShardFilterFor(m writerShardManifest) (string, error) {
	if len(m.Ordinary)+len(m.Posix) == 0 {
		return "", fmt.Errorf("shard %d selects nothing", m.Shard)
	}
	level2 := slices.Clone(m.Ordinary)
	if len(m.Posix) > 0 {
		level2 = append(level2, "posix")
	}
	f := "^TestWriterReplay$/" + quoteAlt(level2)
	if len(m.Posix) > 0 {
		f += "/" + quoteAlt(m.Posix)
	}
	return f, nil
}

// writerShardFilter is the exact -run filter for one shard of TestWriterReplay.
func writerShardFilter(t *testing.T, shard int) string {
	t.Helper()
	if shard < 0 || shard >= writerShardCount {
		t.Fatalf("writer shard %d out of range", shard)
	}
	f, err := writerShardFilterFor(loadWriterShardManifest(t, repoRoot(t), shard))
	if err != nil {
		t.Fatal(err)
	}
	return f
}

// splitRunPattern mirrors testing's splitRegexp: '/' separates levels except
// inside brackets or parentheses.
func splitRunPattern(s string) []string {
	var out []string
	cs, cp, start := 0, 0, 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '[':
			cs++
		case ']':
			cs--
		case '(':
			if cs == 0 {
				cp++
			}
		case ')':
			if cs == 0 {
				cp--
			}
		case '\\':
			i++
		case '/':
			if cs == 0 && cp == 0 {
				out = append(out, s[start:i])
				start = i + 1
			}
		}
	}
	return append(out, s[start:])
}

// filterSelects reports whether the -run pattern selects the leaf test
// TestWriterReplay/<sub>.
func filterSelects(t *testing.T, filter, sub string) bool {
	t.Helper()
	pats := splitRunPattern(filter)
	names := append([]string{"TestWriterReplay"}, strings.Split(sub, "/")...)
	for i, n := range names {
		if i >= len(pats) {
			break
		}
		if !regexp.MustCompile(pats[i]).MatchString(n) {
			return false
		}
	}
	return true
}

// writerReplayCounts is what TestWriterReplay actually did: subtests selected
// by -run (a Windows POSIX skip is selected, not executed), subtests that ran
// past the skip, and golden invocations compared. Subtests run sequentially.
type writerReplayCounts struct{ selected, executed, compared int }

func (c writerReplayCounts) summary() string {
	return fmt.Sprintf("%d selected, %d executed writer cases, %d golden invocations compared", c.selected, c.executed, c.compared)
}

// refusal is the message for a -run filter that selected nothing, else "".
func (c writerReplayCounts) refusal(filter string, templates int) string {
	if c.selected == 0 && filter != "" {
		return fmt.Sprintf("-run %q selects none of the %d writer cases nor the recorder self-test (posixOnly cases are TestWriterReplay/posix/<id>)", filter, templates)
	}
	return ""
}

type writerSourceCase struct {
	id    string
	posix bool
	invs  int
}

func loadWriterSourceCases(t *testing.T, repo string) []writerSourceCase {
	t.Helper()
	var out []writerSourceCase
	for _, tpl := range loadWriterTemplates(t, repo) {
		out = append(out, writerSourceCase{id: tpl.ID, posix: tpl.PosixOnly, invs: len(tpl.Argv)})
	}
	return out
}

// writerShardProblems compares manifests against the source cases; it
// reports missing, duplicate, foreign and misplaced ids and malformed shards.
func writerShardProblems(source []writerSourceCase, ms []writerShardManifest) []string {
	var problems []string
	want := map[string]bool{} // id -> posix
	for _, c := range source {
		want[c.id] = c.posix
	}
	seen := map[string]int{}
	if len(ms) != writerShardCount {
		problems = append(problems, fmt.Sprintf("want %d manifests, have %d", writerShardCount, len(ms)))
	}
	for i, m := range ms {
		if m.Shard != i {
			problems = append(problems, fmt.Sprintf("manifest %d claims shard %d", i, m.Shard))
		}
		for _, list := range []struct {
			ids   []string
			posix bool
		}{{m.Ordinary, false}, {m.Posix, true}} {
			for _, id := range list.ids {
				seen[id]++
				if id == writerRecorderID {
					if !list.posix || i != 0 {
						problems = append(problems, "recorder outside shard 0 posix branch")
					}
					continue
				}
				posix, ok := want[id]
				switch {
				case !ok:
					problems = append(problems, "foreign: "+id)
				case posix != list.posix:
					problems = append(problems, "wrong branch: "+id)
				case writerShardForCase(id) != i:
					problems = append(problems, fmt.Sprintf("wrong shard: %s in %d", id, i))
				}
			}
		}
	}
	for id := range want {
		if seen[id] == 0 {
			problems = append(problems, "missing: "+id)
		}
	}
	if seen[writerRecorderID] != 1 {
		problems = append(problems, fmt.Sprintf("recorder appears %d times", seen[writerRecorderID]))
	}
	for id, n := range seen {
		if n > 1 {
			problems = append(problems, "duplicate: "+id)
		}
	}
	slices.Sort(problems)
	return slices.Compact(problems)
}

// writerShardTable is spec 3.2, written out independently of the generator.
var writerShardTable = [writerShardCount]struct{ cases, golden, pass, skip, compared int }{
	{290, 340, 101, 189, 115},
	{284, 335, 105, 179, 113},
	{260, 319, 101, 159, 114},
	{260, 320, 100, 160, 109},
}

func loadAllWriterShardManifests(t *testing.T, repo string) []writerShardManifest {
	t.Helper()
	var ms []writerShardManifest
	for i := range writerShardCount {
		ms = append(ms, loadWriterShardManifest(t, repo, i))
	}
	return ms
}

func TestWriterShardHashStable(t *testing.T) {
	for id, want := range map[string]int{"propose-sample": 3, "codex-usage": 3, "a": 2, writerRecorderID: 3} {
		if got := writerShardForCase(id); got != want {
			t.Errorf("writerShardForCase(%q) = %d, want %d", id, got, want)
		}
	}
}

func TestWriterShardSourceToShard(t *testing.T) {
	repo := repoRoot(t)
	source := loadWriterSourceCases(t, repo)
	if len(source) != 1094 {
		t.Fatalf("source has %d writer cases, want 1094", len(source))
	}
	ms := loadAllWriterShardManifests(t, repo)
	if p := writerShardProblems(source, ms); len(p) > 0 {
		t.Fatalf("manifests drift from source:\n%s", strings.Join(p, "\n"))
	}
	goldens := loadWriterGoldens(t, repo)
	for i, m := range ms {
		want := writerShardTable[i]
		if got := len(m.Ordinary) + len(m.Posix) - btoi(i == 0); got != want.cases {
			t.Errorf("shard %d: %d cases, want %d", i, got, want.cases)
		}
		if m.Golden != want.golden || m.WindowsPass != want.pass || m.WindowsSkip != want.skip || m.WindowsCompared != want.compared {
			t.Errorf("shard %d: manifest totals %+v, want %+v", i, m, want)
		}
		if len(m.Ordinary) != m.WindowsPass || len(m.Posix)-btoi(i == 0) != m.WindowsSkip {
			t.Errorf("shard %d: branch sizes disagree with windows totals", i)
		}
		// Golden counts recomputed from the golden files, not the manifest.
		golden, compared := 0, 0
		posix := map[string]bool{}
		for _, id := range m.Posix {
			posix[id] = true
		}
		for _, c := range source {
			if writerShardForCase(c.id) != i {
				continue
			}
			for inv := range c.invs {
				if goldens[c.id+"|"+itoa(int64(inv))] != nil {
					golden++
					if !c.posix {
						compared++
					}
				}
			}
		}
		if golden != want.golden || compared != want.compared {
			t.Errorf("shard %d: recomputed golden %d compared %d, want %d and %d", i, golden, compared, want.golden, want.compared)
		}
	}
}

func btoi(b bool) int {
	if b {
		return 1
	}
	return 0
}

func TestWriterShardDriftFixtures(t *testing.T) {
	source := []writerSourceCase{{id: "propose-sample"}, {id: "codex-usage", posix: true}, {id: "a"}}
	good := func() []writerShardManifest {
		ms := make([]writerShardManifest, writerShardCount)
		for i := range ms {
			ms[i].Shard = i
		}
		ms[3].Ordinary = []string{"propose-sample"}
		ms[3].Posix = []string{"codex-usage", writerRecorderID}
		ms[2].Ordinary = []string{"a"}
		return ms
	}
	// recorder is shard 3 in this toy corpus, so it must be rejected there.
	if p := writerShardProblems(source, good()); len(p) != 1 || !strings.Contains(p[0], "recorder outside") {
		t.Fatalf("recorder in shard 3 not rejected: %v", p)
	}
	fix := func(mut func(ms []writerShardManifest)) []string {
		ms := good()
		ms[3].Posix = []string{"codex-usage"}
		ms[0].Posix = []string{writerRecorderID}
		mut(ms)
		return writerShardProblems(source, ms)
	}
	if p := fix(func([]writerShardManifest) {}); len(p) != 0 {
		t.Fatalf("valid fixture rejected: %v", p)
	}
	for name, tc := range map[string]struct {
		mut  func(ms []writerShardManifest)
		want string
	}{
		"missing":      {func(ms []writerShardManifest) { ms[2].Ordinary = nil }, "missing: a"},
		"duplicate":    {func(ms []writerShardManifest) { ms[2].Ordinary = append(ms[2].Ordinary, "a") }, "duplicate: a"},
		"foreign":      {func(ms []writerShardManifest) { ms[1].Ordinary = []string{"nope"} }, "foreign: nope"},
		"wrong shard":  {func(ms []writerShardManifest) { ms[1].Ordinary = []string{"a"}; ms[2].Ordinary = nil }, "wrong shard: a in 1"},
		"wrong branch": {func(ms []writerShardManifest) { ms[3].Ordinary = append(ms[3].Ordinary, "codex-usage") }, "wrong branch: codex-usage"},
		"no recorder":  {func(ms []writerShardManifest) { ms[0].Posix = nil }, "recorder appears 0 times"},
		"two recorder": {func(ms []writerShardManifest) { ms[3].Posix = append(ms[3].Posix, writerRecorderID) }, "recorder appears 2 times"},
		"recorder ord": {func(ms []writerShardManifest) { ms[0].Ordinary = []string{writerRecorderID}; ms[0].Posix = nil }, "recorder outside shard 0 posix branch"},
		"shard number": {func(ms []writerShardManifest) { ms[1].Shard = 2 }, "manifest 1 claims shard 2"},
		"short":        {func(ms []writerShardManifest) {}, ""},
	} {
		ms := good()
		ms[3].Posix = []string{"codex-usage"}
		ms[0].Posix = []string{writerRecorderID}
		tc.mut(ms)
		if name == "short" {
			ms = ms[:3]
			tc.want = "want 4 manifests, have 3"
		}
		if p := writerShardProblems(source, ms); !slices.ContainsFunc(p, func(s string) bool { return strings.Contains(s, tc.want) }) {
			t.Errorf("%s: want problem containing %q, got %v", name, tc.want, p)
		}
	}
}

func TestWriterShardFilters(t *testing.T) {
	repo := repoRoot(t)
	source := loadWriterSourceCases(t, repo)
	var names []string
	for _, c := range source {
		if c.posix {
			names = append(names, "posix/"+c.id)
		} else {
			names = append(names, c.id)
		}
	}
	names = append(names, "posix/"+writerRecorderID)
	counts := map[string]int{}
	for shard := range writerShardCount {
		f := writerShardFilter(t, shard)
		for _, n := range names {
			if filterSelects(t, f, n) {
				counts[n]++
				id := strings.TrimPrefix(n, "posix/")
				if id != writerRecorderID && writerShardForCase(id) != shard {
					t.Errorf("shard %d filter selects %s of shard %d", shard, n, writerShardForCase(id))
				}
				if id == writerRecorderID && shard != 0 {
					t.Errorf("shard %d filter selects the recorder", shard)
				}
			}
		}
		// Branch confusion: an ordinary name under posix/ and vice versa.
		for _, c := range source {
			if c.posix && filterSelects(t, f, c.id) && writerShardForCase(c.id) == shard {
				t.Errorf("shard %d filter selects posix case %s without posix/", shard, c.id)
			}
			if !c.posix && filterSelects(t, f, "posix/"+c.id) {
				t.Errorf("shard %d filter selects ordinary case %s under posix/", shard, c.id)
			}
		}
	}
	if len(names) != 1095 {
		t.Fatalf("%d names, want 1095", len(names))
	}
	for _, n := range names {
		if counts[n] != 1 {
			t.Errorf("%s selected by %d shards, want 1", n, counts[n])
		}
	}
	if _, err := writerShardFilterFor(writerShardManifest{Shard: 1}); err == nil {
		t.Error("empty shard accepted")
	}
	if f, _ := writerShardFilterFor(writerShardManifest{Ordinary: []string{"a.b"}}); filterSelects(t, f, "axb") || !filterSelects(t, f, "a.b") {
		t.Errorf("ids are not quoted in %q", f)
	}
}

// The Python guard (check-writer-replay-shards.py filter) must emit exactly this
// string for the same fixture; check_writer_replay_shards_test.py pins the same
// literal. Real caseIDs never contain '+' or '\\'; the fixture does to cover quoting.
func TestWriterShardFilterPythonGolden(t *testing.T) {
	const want = `^TestWriterReplay$/^(?:a\.b|c\+d|e\\f|posix)$/^(?:p-1|q\+r)$`
	got, err := writerShardFilterFor(writerShardManifest{Ordinary: []string{"a.b", "c+d", `e\f`}, Posix: []string{"p-1", "q+r"}})
	if err != nil {
		t.Fatal(err)
	}
	if got != want {
		t.Errorf("filter = %s, want %s", got, want)
	}
	if got, _ := writerShardFilterFor(writerShardManifest{Ordinary: []string{"a.b"}}); got != `^TestWriterReplay$/^(?:a\.b)$` {
		t.Errorf("ordinary-only filter = %s", got)
	}
}

func TestWriterShardManifestMalformed(t *testing.T) {
	for name, raw := range map[string]string{
		"unknown field": `{"shard":0,"ordinary":[],"posix":[],"golden":0,"windowsPass":0,"windowsSkip":0,"windowsCompared":0,"extra":1}`,
		"trailing":      `{"shard":0} {"shard":1}`,
		"wrong type":    `{"shard":"0"}`,
	} {
		ft := &fatalCatcher{}
		func() {
			defer func() { _ = recover() }()
			parseWriterShardManifest(ft, []byte(raw))
		}()
		if !ft.failed {
			t.Errorf("%s accepted", name)
		}
	}
}

// fatalCatcher records Fatalf instead of ending the test.
type fatalCatcher struct {
	testing.TB
	failed bool
}

func (f *fatalCatcher) Helper() {}
func (f *fatalCatcher) Fatalf(string, ...any) {
	f.failed = true
	panic("fatal")
}
func (f *fatalCatcher) Fatal(...any) { f.failed = true; panic("fatal") }

// TestWriterReplayAccounting: under a filter the summary reports what was
// selected, executed and compared, never the corpus size.
func TestWriterReplayAccounting(t *testing.T) {
	c := writerReplayCounts{}
	c.selected, c.executed, c.compared = 3, 2, 5
	got := c.summary()
	if strings.Contains(got, "1075") || strings.Contains(got, "1295") {
		t.Errorf("summary leaks corpus size: %q", got)
	}
	for _, want := range []string{"3 selected", "2 executed", "5 golden invocations compared"} {
		if !strings.Contains(got, want) {
			t.Errorf("summary %q lacks %q", got, want)
		}
	}
	if (writerReplayCounts{}).refusal("^TestWriterReplay$/^nothing$", 1075) == "" {
		t.Error("zero selection with a -run filter not refused")
	}
	c.selected = 1
	if c.refusal("x", 1075) != "" || (writerReplayCounts{}).refusal("", 1075) != "" {
		t.Error("refused a valid selection or an unfiltered run")
	}
}

// legacyWriterSummary is the pre-change TestWriterReplay summary, retained
// verbatim as a behavioral oracle: it printed the corpus sizes whatever the
// -run filter selected.
func legacyWriterSummary(ran, templates, goldens int) string {
	return fmt.Sprintf("%d of %d writer cases run (%d golden invocations)", ran, templates, goldens)
}

// TestWriterReplayAccountingLegacyWrong shows the old logic misreports a
// filtered run (one case ran, yet 1075 cases and 1295 invocations are
// claimed) and the current logic does not.
func TestWriterReplayAccountingLegacyWrong(t *testing.T) {
	old := legacyWriterSummary(1, 1075, 1295)
	if !strings.Contains(old, "1075") || !strings.Contains(old, "1295") {
		t.Fatalf("legacy summary no longer shows the corpus totals: %q", old)
	}
	c := writerReplayCounts{selected: 1, executed: 1, compared: 1}
	cur := c.summary()
	if strings.Contains(cur, "1075") || strings.Contains(cur, "1295") {
		t.Errorf("filtered summary still reports corpus totals: %q", cur)
	}
	if !strings.Contains(cur, "1 selected, 1 executed") || !strings.Contains(cur, "1 golden invocations compared") {
		t.Errorf("filtered summary does not report actuals: %q", cur)
	}
}
